def _register(name, arxiv, n, k, d, status, locator, family, definition, **extra):
    CODES.append(dict(name=name, arxiv=arxiv, n=n, k=k, d_claimed=d,
                      status=status, locator=locator, **extra))
    _DEFINITIONS[name] = (family, definition)


