def matrices(name):
    """Return the paper's H_X, H_Z as integer rows, and physical length."""
    family, definition = _DEFINITIONS[name]
    if family == "bb":
        (l, m), a, b = definition
        return stabcode.bb_matrices(l, m, a, b)
    if family == "balanced":
        return _balanced_matrices(definition)
    if family == "mm":
        return _mm_matrices(*definition)
    if family == "cc":
        return _cc_matrices(*definition)
    raise ValueError(f"unknown family {family!r}")


def symmetries(name):
    """Candidate check permutations, shared by X and Z row orders."""
    family, definition = _DEFINITIONS[name]
    if family == "bb":
        (l, m), _, _ = definition
        return [[((i + di) % l) * m + (j + dj) % m
                 for i in range(l) for j in range(m)]
                for di, dj in ((1, 0), (0, 1)) if (di and l > 1) or (dj and m > 1)]
    if family == "balanced":
        return _balanced_symmetries(definition)
    if family == "mm":
        periods, polys = definition
        return _mm_symmetries(periods, len(polys))
    if family == "cc":
        return _cc_symmetries(*definition)
    return []


def control_witness(name, basis):
    """A physical-qubit support, independently checked by the plain tests."""
    return list(CONTROL_WITNESSES[name][basis])


