def _group_mul(g,h,group):
    l,m,q=group
    i,j=g; a,b=h
    return ((i+pow(q,j,l)*a)%l,(j+b)%m)

def _regular_rows(group,poly,side):
    l,m,q=group
    rows=[0]*(l*m)
    # Eq49 sends |h> to |g h> (L) or |h g> (R), i.e. column -> row.
    for i in range(l):
        for j in range(m):
            col=i*m+j
            for g in poly:
                a,b=_group_mul(g,(i,j),group) if side=='L' else _group_mul((i,j),g,group)
                rows[a*m+b] ^= 1<<col
    return rows

def _transpose(rows,size):
    out=[0]*size
    for i,row in enumerate(rows):
        for j in stabcode.bits(row):
            out[j] ^= 1<<i
    return out

def _balanced_matrices(entry):
    n,k,d,status,group,a,b,c,e=entry
    ell=group[0]*group[1]
    A=_regular_rows(group,a,'L');B=_regular_rows(group,b,'L')
    C=_regular_rows(group,c,'R');D=_regular_rows(group,e,'R')
    AT=_transpose(A,ell);BT=_transpose(B,ell)
    CT=_transpose(C,ell);DT=_transpose(D,ell)
    hx=[A[i] | (B[i]<<(2*ell)) | (CT[i]<<(4*ell)) for i in range(ell)]
    hx += [(A[i]<<ell) | (B[i]<<(3*ell)) | (DT[i]<<(4*ell)) for i in range(ell)]
    hz=[C[i] | (D[i]<<ell) | (AT[i]<<(4*ell)) for i in range(ell)]
    hz += [(C[i]<<(2*ell)) | (D[i]<<(3*ell)) | (BT[i]<<(4*ell)) for i in range(ell)]
    return hx,hz,5*ell

def _balanced_symmetries(entry):
    group=entry[4]; l,m,q=group;ell=l*m
    t=next(t for t in range(1,m+1) if pow(q,t,l)==1)
    u=math.gcd(l,q-1)
    out=[]
    for i in range(u):
        for j in range(m//t):
            z=(i*l//u,j*t)
            if z==(0,0): continue
            p=[]
            for block in range(2):
                for a in range(l):
                    for b in range(m):
                        c,d=_group_mul(z,(a,b),group)
                        p.append(block*ell+c*m+d)
            out.append(p)
    return out

def _balanced_paper_witnesses(entry):
    n=entry[0];group=entry[4];ell=group[0]*group[1]
    u,v,r,s=_BALANCED_WITNESS_POLYS[n]
    U=_regular_rows(group,u,'L');V=_regular_rows(group,v,'L')
    R=_regular_rows(group,r,'R');S=_regular_rows(group,s,'R')
    # Physical Z errors commute with Hx (driver memory basis X);
    # physical X errors commute with Hz (driver memory basis Z).
    return {'X': U[0] | (V[0]<<(2*ell)), 'Z': R[0] | (S[0]<<ell)}

