def _cc_matrices(p,A,B):
 a,b=len(A),len(B); cells=a*b; half=cells*p; hx=[]; hz=[]
 for i in range(a):
  for j in range(b):
   for t in range(p):
    x=z=0
    for u in range(a):
     for e in A[i][u]: x^=1<<((u*b+j)*p+(t+e)%p)
     for e in A[u][i]: z^=1<<(half+(u*b+j)*p+(t-e)%p)
    for v in range(b):
     for e in B[j][v]: x^=1<<(half+(i*b+v)*p+(t+e)%p)
     for e in B[v][j]: z^=1<<((i*b+v)*p+(t-e)%p)
    hx.append(x); hz.append(z)
 return hx,hz,2*half

def _cc_symmetries(p,A,B):
 cells=len(A)*len(B)
 return [[c*p+(t+s)%p for c in range(cells) for t in range(p)] for s in range(p)]


